import { useEffect, useMemo, useState } from 'react';
import {
  Activity, ArrowRight, Bot, Building2, Check, ChevronRight, CircleDollarSign,
  Database, Download, FileCheck2, Filter, KeyRound, LockKeyhole, Network,
  Pause, Play, Search, ShieldAlert, ShieldCheck, Sparkles, UserRound, Users, X, Zap
} from 'lucide-react';
import {
  humanAdoption,
  licenseRecords, type CisoPage, type EstateAction,
  type EstateEdge, type EstateNode, type InventoryAgent
} from './ciso-model';
import {
  enterpriseEstateEdges as estateEdges, enterpriseEstateNodes as estateNodes,
  enterpriseActions, enterpriseAuditEvents, enterpriseDataFlows, enterpriseEmployees,
  enterpriseInventoryAgents as inventoryAgents, enterpriseStats, enterpriseTasks,
  enterpriseWorkspaceMeshes as workspaceMeshes, type AtomicAuditEvent, type AuditEventCategory, type EnterpriseTask
} from './enterprise-demo';

interface CisoProps {
  page: CisoPage;
  onPageChange: (page: CisoPage) => void;
  onOpenActionCountChange: (count: number) => void;
  notify: (message: string) => void;
}

function loadActions(): EstateAction[] {
  try { const value = localStorage.getItem('h2a-ciso-actions-v3'); return value ? JSON.parse(value) as EstateAction[] : enterpriseActions; }
  catch { return enterpriseActions; }
}

export function CisoPlatform({ page, onPageChange, onOpenActionCountChange, notify }: CisoProps): React.JSX.Element {
  const [actions, setActions] = useState<EstateAction[]>(loadActions);
  const [agents, setAgents] = useState<InventoryAgent[]>(inventoryAgents);
  const [selectedNodeId, setSelectedNodeId] = useState('hq');
  const [selectedAgentId, setSelectedAgentId] = useState<string | null>(null);
  const [selectedActionId, setSelectedActionId] = useState<string | null>(null);
  const [selectedEvidenceId, setSelectedEvidenceId] = useState(enterpriseTasks[0].evidenceId);
  useEffect(() => { window.scrollTo({ top: 0 }); }, [page]);
  useEffect(() => {
    localStorage.setItem('h2a-ciso-actions-v3', JSON.stringify(actions));
    onOpenActionCountChange(actions.filter((action) => action.status === 'open').length);
  }, [actions, onOpenActionCountChange]);

  function resolveAction(id: string, status: EstateAction['status']): void {
    setActions((current) => current.map((item) => item.id === id ? { ...item, status } : item));
    if (id === 'shadow-windsurf' && status === 'contained') setAgents((current) => current.map((agent) => agent.id === 'windsurf' ? { ...agent, state: 'quarantined', risk: 'high' } : agent));
    notify(status === 'contained' ? 'Connection quarantined. New calls are stopped in this demo state.' : status === 'assigned' ? 'Accountable owner assigned.' : 'Decision recorded for this exact purpose.');
  }

  const shared = { actions, agents, selectedNodeId, setSelectedNodeId, selectedAgentId, setSelectedAgentId, selectedActionId, setSelectedActionId, selectedEvidenceId, setSelectedEvidenceId, resolveAction, onPageChange, notify };
  return <div className="ciso-root">
    {page === 'overview' ? <EstateOverview {...shared} /> : null}
    {page === 'mesh' ? <MeshPage {...shared} /> : null}
    {page === 'inventory' ? <InventoryPage {...shared} /> : null}
    {page === 'adoption' ? <AdoptionPage {...shared} /> : null}
    {page === 'flows' ? <FlowsPage {...shared} /> : null}
    {page === 'licenses' ? <LicensesPage {...shared} /> : null}
    {page === 'actions' ? <ActionsPage {...shared} /> : null}
    {page === 'evidence' ? <EvidencePage {...shared} /> : null}
    {selectedAgentId ? <AgentDrawer agent={agents.find((agent) => agent.id === selectedAgentId) ?? agents[0]} onClose={() => setSelectedAgentId(null)} onContain={() => { const agent = agents.find((item) => item.id === selectedAgentId); setAgents((current) => current.map((item) => item.id === selectedAgentId ? { ...item, state: 'quarantined', risk: 'high' } : item)); setSelectedAgentId(null); notify(`${agent?.name} quarantined in the demo estate.`); }} /> : null}
  </div>;
}

interface SharedProps {
  actions: EstateAction[]; agents: InventoryAgent[]; selectedNodeId: string;
  setSelectedNodeId: (id: string) => void; selectedAgentId: string | null;
  setSelectedAgentId: (id: string | null) => void; selectedActionId: string | null;
  setSelectedActionId: (id: string | null) => void;
  selectedEvidenceId: string; setSelectedEvidenceId: (id: string) => void;
  resolveAction: (id: string, status: EstateAction['status']) => void;
  onPageChange: (page: CisoPage) => void; notify: (message: string) => void;
}

function EstateOverview(props: SharedProps): React.JSX.Element {
  const open = props.actions.filter((action) => action.status === 'open');
  return <div className="page ciso-page"><CisoHeader eyebrow="Enterprise AI command center" title="AI estate" subtitle="One operational view of people, agents, tools, data movement, risk, and spend." actions={<><button className="secondary-button" onClick={() => props.onPageChange('evidence')}><FileCheck2 size={17} />Evidence</button><button className="primary-button" onClick={() => props.onPageChange('actions')}><ShieldAlert size={17} />{open.length} actions need review</button></>} />
    <section className="estate-kpis"><Kpi value={enterpriseStats.activeEmployees.toString()} label="Active humans" detail={`of ${enterpriseStats.employees} enrolled`} trend="+8.4%" tone="blue" icon={<Users />} /><Kpi value={enterpriseStats.activeAgents.toString()} label="Active agents" detail={`of ${enterpriseStats.agents} discovered`} trend="+21 this month" tone="teal" icon={<Bot />} /><Kpi value={enterpriseStats.workspaces.toString()} label="Workspaces" detail={`${enterpriseStats.crossWorkspaceFlows} cross-workspace flows`} trend="2 unusual" tone="violet" icon={<Building2 />} /><Kpi value="18" label="AI tools" detail="3 unmanaged" trend="1 critical" tone="amber" icon={<Sparkles />} /><Kpi value="$38.4k" label="Monthly spend" detail="$9.7k reclaimable" trend="25% waste" tone="neutral" icon={<CircleDollarSign />} /></section>
    <div className="estate-split"><section className="ciso-panel"><PanelHeader icon={<Users />} title="Human adoption" subtitle="Usage, accountability, and cross-workspace behavior" action={<button className="text-button" onClick={() => props.onPageChange('adoption')}>Open adoption <ArrowRight size={16} /></button>} /><div className="adoption-summary"><div><strong>{Math.round(enterpriseStats.activeEmployees / enterpriseStats.employees * 100)}%</strong><span>30-day adoption</span><small>{enterpriseStats.activeEmployees} of {enterpriseStats.employees} people</small></div><MiniBars values={[62, 67, 71, 74, 78, 81, 84]} tone="blue" /><div className="rank-list">{humanAdoption.slice(0, 3).map((human, index) => <button key={human.name} onClick={() => props.onPageChange('adoption')}><span className="rank">{index + 1}</span><span><strong>{human.name}</strong><small>{human.team}</small></span><b>{human.calls.toLocaleString()} calls</b></button>)}</div></div></section>
      <section className="ciso-panel"><PanelHeader icon={<Bot />} title="Agent and tool estate" subtitle="Lifecycle, usage, ownership, and control coverage" action={<button className="text-button" onClick={() => props.onPageChange('inventory')}>Open inventory <ArrowRight size={16} /></button>} /><div className="agent-estate-summary"><div className="estate-donut" style={{ '--donut': '327deg' } as React.CSSProperties}><strong>{Math.round(enterpriseStats.activeAgents / enterpriseStats.agents * 100)}%</strong><small>active</small></div><dl><div><dt>Company</dt><dd>{enterpriseStats.companyAgents}</dd></div><div><dt>Third-party</dt><dd>{enterpriseStats.thirdPartyAgents}</dd></div><div><dt>All discovered</dt><dd>{enterpriseStats.agents}</dd></div><div><dt>New / retired</dt><dd>+21 / 8</dd></div></dl><div className="rank-list compact">{props.agents.slice().sort((a, b) => b.calls - a.calls).slice(0, 3).map((agent, index) => <button key={agent.id} onClick={() => props.setSelectedAgentId(agent.id)}><span className="rank">{index + 1}</span><span><strong>{agent.name}</strong><small>{agent.kind}</small></span><b>{agent.calls.toLocaleString()}</b></button>)}</div></div></section></div>
    <div className="ciso-overview-grid"><section className="ciso-panel mesh-overview"><PanelHeader icon={<Network />} title="Enterprise workspace map" subtitle="Headquarters, accountable creators, and workspace communication" action={<button className="text-button" onClick={() => props.onPageChange('mesh')}>Investigate map <ArrowRight size={16} /></button>} /><EstateMesh compact selectedId={props.selectedNodeId} onSelect={props.setSelectedNodeId} onEnterWorkspace={(id) => { props.setSelectedNodeId(id); props.onPageChange('mesh'); }} /></section><section className="ciso-panel action-overview"><PanelHeader icon={<ShieldAlert />} title="Action queue" subtitle="Highest-impact controls first" action={<button className="text-button" onClick={() => props.onPageChange('actions')}>View all</button>} /><ActionList actions={open.slice(0, 4)} onOpen={(id) => { props.setSelectedActionId(id); props.onPageChange('actions'); }} /></section></div>
    <section className="ciso-panel ciso-outcomes"><PanelHeader icon={<ShieldCheck />} title="Control outcomes · last 30 days" subtitle="Security and economic value created by H2A" /><div><Outcome value="148" label="Unmanaged calls blocked" tone="red" /><Outcome value="2.4 TB" label="Sensitive data withheld" tone="cyan" /><Outcome value="37" label="Owners restored" tone="teal" /><Outcome value="$116k" label="Annual waste identified" tone="violet" /><Outcome value="96.8%" label="Policy-covered activity" tone="blue" /></div></section>
  </div>;
}

function MeshPage(props: SharedProps): React.JSX.Element {
  const initialWorkspace = props.selectedNodeId.startsWith('ws-') ? props.selectedNodeId : null;
  const [workspaceId, setWorkspaceId] = useState<string | null>(initialWorkspace);
  const [range, setRange] = useState('24h');
  const [filter, setFilter] = useState('all');
  const [playing, setPlaying] = useState(false);
  const [query, setQuery] = useState('');
  const workspace = workspaceId ? workspaceMeshes[workspaceId] : null;
  const graphNodes = workspace?.nodes ?? estateNodes;
  const graphEdges = workspace?.edges ?? estateEdges;
  const rootId = workspaceId ?? 'hq';
  const selected = graphNodes.find((node) => node.id === props.selectedNodeId) ?? graphNodes.find((node) => node.id === rootId) ?? graphNodes[0];
  const workspaceName = workspace?.nodes.find((node) => node.id === workspaceId)?.label;
  const searchResults = useMemo(() => query.trim() ? graphNodes.filter((node) => `${node.label} ${node.owner ?? ''} ${node.scope}`.toLowerCase().includes(query.toLowerCase())).slice(0, 6) : [], [graphNodes, query]);
  useEffect(() => { window.scrollTo({ top: 0 }); }, [workspaceId]);

  function enterWorkspace(id: string): void {
    setWorkspaceId(id);
    setFilter('all');
    setQuery('');
    props.setSelectedNodeId(id);
  }

  function returnToHeadquarters(): void {
    setWorkspaceId(null);
    setFilter('all');
    setQuery('');
    props.setSelectedNodeId('hq');
  }

  function selectSearchResult(node: EstateNode): void {
    setQuery(node.label);
    props.setSelectedNodeId(node.id);
    if (!workspace && node.type === 'workspace') enterWorkspace(node.id);
  }

  return <div className="page ciso-page mesh-page"><CisoHeader eyebrow={workspace ? 'Workspace topology' : 'Enterprise topology'} title={workspace ? `${workspaceName} workspace` : 'Enterprise workspace map'} subtitle={workspace ? 'People and agents operating inside this workspace. Lines show membership, commands, approvals, and agent handoffs.' : 'Headquarters connects to accountable workspace creators. Dotted lines show active communication between workspaces.'} actions={<>{workspace ? <button className="secondary-button" onClick={returnToHeadquarters}><ArrowRight className="back-arrow" size={17} />Back to headquarters</button> : null}<div className="segmented-control">{['24h', '7d', '30d'].map((item) => <button className={range === item ? 'active' : ''} key={item} onClick={() => setRange(item)}>{item}</button>)}</div></>} /><section className="mesh-scale-summary"><InlineStat label="Employees" value={enterpriseStats.employees} /><InlineStat label="Persistent workspaces" value={enterpriseStats.workspaces} /><InlineStat label="Agents discovered" value={enterpriseStats.agents} /><InlineStat label="Company agents" value={enterpriseStats.companyAgents} /><InlineStat label="Cross-workspace flows" value={enterpriseStats.crossWorkspaceFlows} warning /></section><div className="mesh-toolbar"><div className="mesh-search-wrap"><label className="local-search"><Search size={17} /><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder={workspace ? 'Find a member or agent in this workspace' : 'Find a workspace creator or workspace'} /></label>{searchResults.length ? <div className="mesh-search-results">{searchResults.map((node) => <button key={node.id} onClick={() => selectSearchResult(node)}><NodeIcon node={node} /><span><strong>{node.label}</strong><small>{node.subtitle}</small></span><ChevronRight size={15} /></button>)}</div> : null}</div>{workspace ? <label className="select-control"><Filter size={17} /><select value={filter} onChange={(event) => setFilter(event.target.value)}><option value="all">People and agents</option><option value="people">People only</option><option value="agents">All agents</option><option value="third-party">Third-party agents</option></select></label> : null}<button className="secondary-button" onClick={() => setPlaying(!playing)}>{playing ? <Pause size={17} /> : <Play size={17} />}{playing ? 'Pause activity' : 'Show live activity'}</button></div><div className="mesh-workbench"><section className={`ciso-panel full-mesh ${playing ? 'is-playing' : ''}`}><EstateMesh nodes={graphNodes} edges={graphEdges} rootId={rootId} selectedId={selected.id} onSelect={props.setSelectedNodeId} onEnterWorkspace={workspace ? undefined : enterWorkspace} filter={filter} query={query} /><MeshLegend workspaceView={Boolean(workspace)} /></section><aside className="ciso-panel mesh-inspector"><span className={`entity-symbol ${selected.type}`}><NodeIcon node={selected} /></span><span className="eyebrow">{nodeTypeLabel(selected.type)}</span><h2>{selected.label}</h2><p>{selected.subtitle}</p><span className={`risk-chip ${selected.risk}`}>{selected.risk} risk</span><dl className="inspection-facts"><div><dt>Accountable owner</dt><dd>{selected.owner}</dd></div><div><dt>Current activity</dt><dd>{selected.activity}</dd></div><div><dt>Authorized scope</dt><dd>{selected.scope}</dd></div><div><dt>Window</dt><dd>{range} activity</dd></div></dl><button className="primary-button full-button" onClick={() => selected.risk === 'critical' ? props.onPageChange('actions') : props.onPageChange('evidence')}>{selected.risk === 'critical' ? 'Open containment action' : 'Open evidence trail'}</button>{workspace ? <button className="secondary-button full-button" onClick={() => props.notify(`Showing only ${selected.label} and its direct workspace relationships.`)}>Show direct relationships</button> : null}</aside></div>{workspace ? <WorkspaceOperations workspaceId={workspaceId!} onOpenEvidence={(task) => { props.setSelectedEvidenceId(task.evidenceId); props.onPageChange('evidence'); }} /> : null}</div>;
}

function WorkspaceOperations({ workspaceId, onOpenEvidence }: { workspaceId: string; onOpenEvidence: (task: EnterpriseTask) => void }): React.JSX.Element {
  const tasks = enterpriseTasks.filter((task) => task.workspaceId === workspaceId);
  return <section className="ciso-panel workspace-operations"><PanelHeader icon={<Activity />} title="Workspace operations and evidence" subtitle="Every active, completed, blocked, and approval-bound task in this room" /><div className="workspace-operation-summary"><span><strong>{tasks.length}</strong> tasks</span><span><strong>{tasks.reduce((sum, task) => sum + task.apiCalls, 0)}</strong> API calls</span><span><strong>{tasks.filter((task) => task.status === 'blocked').length}</strong> blocked</span><span><strong>{tasks.filter((task) => task.status === 'awaiting-approval').length}</strong> awaiting human</span></div><div className="workspace-operation-table"><div className="workspace-operation-head"><span>Task</span><span>Initiated by</span><span>Lead agent / API</span><span>Authorization</span><span>State</span><span /></div>{tasks.map((task) => <button key={task.id} onClick={() => onOpenEvidence(task)}><span><strong>{task.title}</strong><small>{task.size} · {task.purpose}</small></span><span><strong>{task.initiatedBy}</strong><small>{task.initiatorRole}</small></span><span><strong>{task.leadAgent}</strong><small>{task.provider} · {task.apiCalls} calls</small></span><span><strong>{task.authorizedBy}</strong><small>{task.humanReview}</small></span><span><RiskChip risk={task.risk} label={task.status} /></span><ChevronRight size={16} /></button>)}</div></section>;
}

function InventoryPage(props: SharedProps): React.JSX.Element {
  const [query, setQuery] = useState(''); const [kind, setKind] = useState('all'); const [limit, setLimit] = useState(50);
  const filtered = props.agents.filter((agent) => (kind === 'all' || agent.kind === kind) && `${agent.name} ${agent.provider} ${agent.owner}`.toLowerCase().includes(query.toLowerCase()));
  const visible = filtered.slice(0, limit);
  useEffect(() => setLimit(50), [query, kind]);
  return <div className="page ciso-page"><CisoHeader eyebrow="Discovered AI assets" title="AI inventory" subtitle="Every managed, third-party, local, and shadow agent in one accountable registry." actions={<button className="primary-button" onClick={() => props.notify('Discovery scan started for the demo estate.')}><Search size={17} />Run discovery</button>} /><section className="inventory-stats"><InlineStat label="Discovered" value={props.agents.length} /><InlineStat label="Active today" value={props.agents.filter((agent) => agent.state === 'active').length} /><InlineStat label="Company agents" value={props.agents.filter((agent) => agent.kind === 'Company agent').length} /><InlineStat label="Third-party" value={props.agents.filter((agent) => agent.kind === 'Approved third-party' || agent.kind === 'Shadow AI').length} warning /><InlineStat label="Quarantined" value={props.agents.filter((agent) => agent.state === 'quarantined').length} /></section><div className="inventory-toolbar"><label className="local-search"><Search size={17} /><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Search agents, providers, or owners" /></label><label className="select-control"><Filter size={17} /><select value={kind} onChange={(event) => setKind(event.target.value)}><option value="all">All classes</option>{[...new Set(props.agents.map((agent) => agent.kind))].map((item) => <option key={item}>{item}</option>)}</select></label><span className="inventory-result-count">Showing {visible.length} of {filtered.length}</span></div><section className="ciso-panel inventory-table-wrap"><div className="ciso-table inventory-table"><div className="ciso-table-head"><span>Agent or tool</span><span>Class</span><span>Owner</span><span>30d calls</span><span>Users</span><span>Data</span><span>Risk</span><span /></div>{visible.map((agent) => <button className="ciso-table-row" key={agent.id} onClick={() => props.setSelectedAgentId(agent.id)}><span className="agent-name-cell"><span className={`entity-symbol ${agent.kind === 'Shadow AI' ? 'third-party critical' : agent.kind === 'Approved third-party' ? 'third-party' : 'managed-agent'}`}><Bot /></span><span><strong>{agent.name}</strong><small>{agent.provider} · {agent.lastUsed}</small></span></span><span>{agent.kind}</span><span>{agent.owner}</span><b>{agent.calls.toLocaleString()}</b><span>{agent.users}</span><span>{agent.data}</span><span><RiskChip risk={agent.risk} /></span><ChevronRight /></button>)}</div>{visible.length < filtered.length ? <button className="inventory-load-more" onClick={() => setLimit((current) => current + 50)}>Load 50 more agents</button> : null}</section></div>;
}

function AdoptionPage(props: SharedProps): React.JSX.Element {
  return <div className="page ciso-page"><CisoHeader eyebrow="Human adoption and accountability" title="People & adoption" subtitle="Understand who uses AI, who owns agents, and where behavior crosses normal team boundaries." /><section className="estate-kpis adoption-kpis"><Kpi value={enterpriseStats.activeEmployees.toString()} label="30-day active people" detail={`${Math.round(enterpriseStats.activeEmployees / enterpriseStats.employees * 100)}% enterprise adoption`} trend="+8.4%" tone="blue" icon={<Users />} /><Kpi value="163" label="Agent owners" detail="1:2.0 owner-to-agent ratio" trend="4 unowned" tone="teal" icon={<UserRound />} /><Kpi value="46" label="Cross-workspace operators" detail={`${enterpriseStats.crossWorkspaceFlows} active data paths`} trend="2 unusual" tone="amber" icon={<Network />} /><Kpi value="38" label="Dormant licenses" detail="No use in 30 days" trend="$9.7k / month" tone="violet" icon={<CircleDollarSign />} /></section><div className="adoption-grid"><section className="ciso-panel"><PanelHeader icon={<Activity />} title="Adoption by team" subtitle="Active people as a share of enrolled people" /><TeamBar name="Digital Commerce" active={18} total={20} /><TeamBar name="Enterprise Security" active={19} total={20} /><TeamBar name="Platform Engineering" active={17} total={20} /><TeamBar name="Customer Support" active={16} total={20} /><TeamBar name="Finance Operations" active={15} total={20} /><TeamBar name="People Operations" active={17} total={20} /></section><section className="ciso-panel"><PanelHeader icon={<Network />} title="Cross-workspace behavior" subtitle="People active across multiple security boundaries" /><div className="signal-list"><Signal tone="critical" title="Asha Mehta" detail="Customer context moved across 2 workspaces" action="Investigate" onClick={() => props.onPageChange('mesh')} /><Signal tone="warning" title="Elena Garcia" detail="Research Scout accessed 2 workspace scopes" action="Review scope" onClick={() => props.onPageChange('mesh')} /><Signal tone="healthy" title="Varun Khatr" detail="Security administration across 2 approved spaces" action="Expected" onClick={() => props.notify('Activity matches Varun’s approved enterprise role.')} /></div></section></div><section className="ciso-panel"><PanelHeader icon={<Users />} title="Top AI operators" subtitle="Usage is paired with ownership and risk context" /><div className="ciso-table human-table"><div className="ciso-table-head"><span>Person</span><span>Team</span><span>30d calls</span><span>Owned agents</span><span>Workspaces</span><span>Signal</span></div>{humanAdoption.map((human) => <button className="ciso-table-row" key={human.name} onClick={() => props.onPageChange('mesh')}><span className="agent-name-cell"><span className="human-dot">{human.name.split(' ').map((part) => part[0]).join('')}</span><strong>{human.name}</strong></span><span>{human.team}</span><b>{human.calls.toLocaleString()}</b><span>{human.agents}</span><span>{human.workspaces}</span><span className={human.risk === 'Healthy' ? 'healthy-text' : 'risk-text'}>{human.risk}</span></button>)}</div></section><EmployeeDirectory notify={props.notify} /></div>;
}

function EmployeeDirectory({ notify }: { notify: (message: string) => void }): React.JSX.Element {
  const [query, setQuery] = useState('');
  const [limit, setLimit] = useState(50);
  const filtered = enterpriseEmployees.filter((employee) => `${employee.name} ${employee.team} ${employee.role}`.toLowerCase().includes(query.toLowerCase()));
  useEffect(() => setLimit(50), [query]);
  return <section className="ciso-panel employee-directory"><PanelHeader icon={<Users />} title="Enterprise employee oversight" subtitle="All enrolled people, their agent ownership, workspace reach, and current activity" /><div className="employee-directory-toolbar"><label className="local-search"><Search size={16} /><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Search 200 employees" /></label><span>Showing {Math.min(limit, filtered.length)} of {filtered.length}</span></div><div className="employee-directory-table"><div className="employee-directory-head"><span>Employee</span><span>Team</span><span>Role</span><span>Agents</span><span>Workspaces</span><span>Status</span></div>{filtered.slice(0, limit).map((employee) => <button key={employee.id} onClick={() => notify(`${employee.name}: ${employee.agents} agents across ${employee.workspaces} workspaces.`)}><span className="agent-name-cell"><span className="human-dot">{employee.name.split(' ').map((part) => part[0]).slice(0, 2).join('')}</span><strong>{employee.name}</strong></span><span>{employee.team}</span><span>{employee.role}</span><b>{employee.agents}</b><b>{employee.workspaces}</b><span className={`employee-status ${employee.status}`}><i />{employee.status}</span></button>)}</div>{limit < filtered.length ? <button className="inventory-load-more" onClick={() => setLimit((current) => current + 50)}>Load 50 more employees</button> : null}</section>;
}

function FlowsPage(props: SharedProps): React.JSX.Element {
  const blocked = enterpriseDataFlows.filter((flow) => flow.result === 'Blocked').length;
  const review = enterpriseDataFlows.filter((flow) => flow.result === 'Review').length;
  function openFlow(evidenceId: string): void { props.setSelectedEvidenceId(evidenceId); props.onPageChange('evidence'); }
  return <div className="page ciso-page"><CisoHeader eyebrow="Context and destination control" title="Data flows" subtitle="See who initiated every cross-workspace transfer, who authorized it, what was released, and where it went." actions={<button className="secondary-button" onClick={() => props.onPageChange('mesh')}><Network size={17} />View in mesh</button>} /><section className="estate-kpis flow-kpis"><Kpi value="18.6 TB" label="Agent data processed" detail="Last 30 days" trend="+12%" tone="blue" icon={<Database />} /><Kpi value="2.4 TB" label="Sensitive data withheld" detail="Across 6,812 requests" trend="Policy protected" tone="teal" icon={<LockKeyhole />} /><Kpi value={enterpriseDataFlows.length.toString()} label="Cross-workspace paths" detail={`${review} need review`} trend={`${blocked} blocked`} tone="amber" icon={<Network />} /><Kpi value="27" label="External destinations" detail="24 approved · 3 shadow" trend="Review" tone="violet" icon={<ArrowRight />} /></section><div className="flow-map ciso-panel"><PanelHeader icon={<Database />} title="Cross-workspace transfer ledger" subtitle="Source → actor and agent → destination · every row opens its evidence" /><div className="flow-lanes detailed">{enterpriseDataFlows.map((flow) => <button key={flow.id} onClick={() => openFlow(flow.evidenceId)}><span className="flow-endpoint"><Building2 /><strong>{flow.from}</strong><small>Initiated by {flow.actor}</small></span><span className={`flow-path ${flow.risk}`}><i /><small>{flow.agent} · {flow.provider}<br />{flow.data} · {flow.volume}</small></span><span className="flow-endpoint"><Database /><strong>{flow.to}</strong><small>Authorized by {flow.authorizedBy}</small></span><RiskChip risk={flow.risk} label={flow.result} /></button>)}</div></div></div>;
}

function LicensesPage(props: SharedProps): React.JSX.Element {
  const waste = licenseRecords.reduce((sum, license) => sum + (license.purchased - license.active), 0);
  return <div className="page ciso-page"><CisoHeader eyebrow="Adoption and spend" title="AI license intelligence" subtitle="Connect purchased capacity to real human and agent activity before renewal." actions={<button className="primary-button" onClick={() => props.notify('License optimization report prepared from the demo dataset.')}><Download size={17} />Optimization report</button>} /><section className="license-summary"><div><span>Purchased seats</span><strong>1,640</strong><small>Across 5 enterprise platforms</small></div><div><span>Active seats</span><strong>1,212</strong><small>74% utilization</small></div><div className="waste"><span>Reclaimable seats</span><strong>{waste}</strong><small>$9.7k monthly opportunity</small></div><div><span>Annualized spend</span><strong>$580k</strong><small>Contracted AI tooling</small></div></section><section className="ciso-panel license-table"><PanelHeader icon={<CircleDollarSign />} title="License portfolio" subtitle="Purchased capacity compared with observed 30-day use" /><div className="license-list">{licenseRecords.map((license) => { const percent = Math.round(license.active / license.purchased * 100); return <button key={license.id} onClick={() => props.notify(`${license.tool}: ${license.purchased - license.active} seats are currently reclaimable.`)}><span className="license-brand"><span>{license.tool.slice(0, 1)}</span><span><strong>{license.tool}</strong><small>{license.provider} · owner {license.owner}</small></span></span><span className="license-util"><span><b>{license.active}</b> / {license.purchased} active</span><span className="util-track"><i style={{ width: `${percent}%` }} /></span><small>{percent}% utilization</small></span><MiniBars values={license.trend} tone={percent < 60 ? 'amber' : 'teal'} /><span><strong>${license.monthlyCost.toLocaleString()}</strong><small>per month</small></span><span><strong>{license.renewal}</strong><small>renewal</small></span><ChevronRight /></button>; })}</div></section></div>;
}

function ActionsPage(props: SharedProps): React.JSX.Element {
  const selected = props.actions.find((action) => action.id === props.selectedActionId) ?? props.actions.find((action) => action.status === 'open') ?? props.actions[0];
  const [filter, setFilter] = useState('open');
  const visible = props.actions.filter((action) => filter === 'all' || action.status === filter);
  return <div className="page ciso-page"><CisoHeader eyebrow="Operator action queue" title="Investigate and contain" subtitle="Every item explains the actor, reason, requested data, destination, policy result, and recommended control." /><div className="actions-workbench"><section className="ciso-panel action-list-panel"><div className="panel-filter-row"><div className="segmented-control"><button className={filter === 'open' ? 'active' : ''} onClick={() => setFilter('open')}>Open</button><button className={filter === 'all' ? 'active' : ''} onClick={() => setFilter('all')}>All</button></div><span>{visible.length} items</span></div><ActionList actions={visible} selectedId={selected.id} onOpen={props.setSelectedActionId} /></section><aside className="ciso-panel action-inspector"><div className="action-title-row"><span className={`risk-symbol ${selected.risk}`}><ShieldAlert /></span><div><span className="eyebrow">{selected.category}</span><h2>{selected.title}</h2></div></div><p>{selected.summary}</p><RiskChip risk={selected.risk} /><dl className="inspection-facts"><div><dt>Initiated by</dt><dd>{selected.actor}</dd></div><div><dt>Agent or destination</dt><dd>{selected.target}</dd></div><div><dt>Data involved</dt><dd>{selected.data}</dd></div><div><dt>Workspace path</dt><dd>{selected.workspace}</dd></div><div><dt>Detected</dt><dd>{selected.detected}</dd></div><div><dt>Status</dt><dd>{selected.status}</dd></div></dl><div className="recommendation"><Sparkles /><span><strong>Recommended action</strong><small>{selected.recommended}</small></span></div>{selected.status === 'open' ? <div className="containment-actions"><button className="danger-button" onClick={() => props.resolveAction(selected.id, 'contained')}>Contain now</button><button className="secondary-button" onClick={() => props.resolveAction(selected.id, 'assigned')}>Assign owner</button><button className="secondary-button" onClick={() => props.resolveAction(selected.id, 'approved')}>Approve once</button></div> : <div className="resolved-state"><CheckCircle /><span><strong>{selected.status}</strong><small>Recorded by Varun Khatr in the local demo state.</small></span></div>}<button className="text-button" onClick={() => { if (selected.evidenceId) props.setSelectedEvidenceId(selected.evidenceId); props.onPageChange('evidence'); }}>Open full evidence trail <ArrowRight size={16} /></button></aside></div></div>;
}

function EvidencePage(props: SharedProps): React.JSX.Element {
  const [query, setQuery] = useState('');
  const [status, setStatus] = useState('all');
  const [limit, setLimit] = useState(60);
  const filtered = enterpriseTasks.filter((task) => (status === 'all' || task.status === status) && `${task.title} ${task.workspace} ${task.initiatedBy} ${task.leadAgent} ${task.traceId}`.toLowerCase().includes(query.toLowerCase()));
  const selected = enterpriseTasks.find((task) => task.evidenceId === props.selectedEvidenceId) ?? filtered[0] ?? enterpriseTasks[0];
  useEffect(() => setLimit(60), [query, status]);
  return <div className="page ciso-page">
    <CisoHeader eyebrow="Readable investigation record" title="Evidence trail" subtitle="Trace every task from human intent to atomic control events, provider calls, effects, and final state." actions={<button className="secondary-button" onClick={() => downloadJson(`${selected.evidenceId}.json`, { task: selected, events: enterpriseAuditEvents.filter((event) => event.taskId === selected.id) })}><Download size={17} />Export selected trail</button>} />
    <section className="evidence-stats"><InlineStat label="Task evidence records" value={enterpriseTasks.length} /><InlineStat label="Atomic audit events" value={enterpriseAuditEvents.length} /><InlineStat label="Provider calls" value={enterpriseAuditEvents.filter((event) => event.category === 'provider-call').length} /><InlineStat label="Blocked" value={enterpriseTasks.filter((task) => task.status === 'blocked').length} danger /><InlineStat label="Awaiting human" value={enterpriseTasks.filter((task) => task.status === 'awaiting-approval').length} warning /></section>
    <div className="evidence-browser">
      <aside className="ciso-panel evidence-index"><div className="evidence-index-controls"><label className="local-search"><Search size={16} /><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Search task, person, agent, or trace" /></label><label className="select-control"><Filter size={16} /><select value={status} onChange={(event) => setStatus(event.target.value)}><option value="all">All task states</option><option value="running">Running</option><option value="completed">Completed</option><option value="blocked">Blocked</option><option value="awaiting-approval">Awaiting approval</option></select></label><small>{filtered.length} records</small></div><div className="evidence-case-list">{filtered.slice(0, limit).map((task) => <button className={task.evidenceId === selected.evidenceId ? 'selected' : ''} key={task.evidenceId} onClick={() => props.setSelectedEvidenceId(task.evidenceId)}><span className={`evidence-state ${task.status}`} /><span><strong>{task.title}</strong><small>{task.workspace} · {task.initiatedBy}</small></span><RiskChip risk={task.risk} /><ChevronRight size={15} /></button>)}</div>{limit < filtered.length ? <button className="evidence-load-more" onClick={() => setLimit((current) => current + 60)}>Load 60 more records</button> : null}</aside>
      <div className="evidence-detail">
        <section className="ciso-panel evidence-story"><div className="evidence-case-header"><span className={`risk-symbol ${selected.risk}`}><ShieldAlert /></span><div><span className="eyebrow">{selected.evidenceId} · {selected.size} task</span><h2>{selected.title}</h2><p>{selected.workspace} · started {selected.started}</p></div><RiskChip risk={selected.risk} label={selected.status} /></div>{selected.blockedReason ? <div className="evidence-blocker"><ShieldAlert /><span><strong>{selected.blockedReason}</strong><small>{selected.remedy}</small></span></div> : null}<TaskTraceExplorer task={selected} /></section>
        <aside className="ciso-panel evidence-context"><PanelHeader icon={<KeyRound />} title="Authority and data" subtitle="What the selected record proves" /><dl className="inspection-facts"><div><dt>Initiated by</dt><dd>{selected.initiatedBy} · {selected.initiatorRole}</dd></div><div><dt>Authorized by</dt><dd>{selected.authorizedBy}</dd></div><div><dt>Human in loop</dt><dd>{selected.humanReview}</dd></div><div><dt>Lead agent</dt><dd>{selected.leadAgent} · {selected.provider}</dd></div><div><dt>Purpose</dt><dd>{selected.purpose}</dd></div><div><dt>Released</dt><dd>{selected.released}</dd></div><div><dt>Withheld</dt><dd>{selected.withheld}</dd></div><div><dt>Destination</dt><dd>{selected.destination}</dd></div><div><dt>Output</dt><dd>{selected.output}</dd></div></dl><details open><summary>Task-level receipts</summary><code>{selected.traceId}</code><code>{selected.apiEndpoint} · {selected.apiCalls} calls</code><code>mandate_{selected.id}_approved</code><code>context_{selected.evidenceId}_bounded</code></details><button className="primary-button full-button" onClick={() => props.onPageChange('actions')}>Open related controls</button></aside>
      </div>
    </div>
    <AtomicEventLedger />
  </div>;
}

function TaskTraceExplorer({ task }: { task: EnterpriseTask }): React.JSX.Element {
  const events = enterpriseAuditEvents.filter((event) => event.taskId === task.id);
  const [selectedId, setSelectedId] = useState(events[0]?.id ?? '');
  useEffect(() => setSelectedId(events[0]?.id ?? ''), [task.id]);
  const selected = events.find((event) => event.id === selectedId) ?? events[0];
  return <div className="task-trace"><header><span><Network size={16} /><strong>Execution trace</strong></span><code>{task.traceId}</code><small>{events.length} atomic events</small></header><div className="trace-ancestry"><span>Enterprise</span><ChevronRight size={13} /><span>{task.workspace}</span><ChevronRight size={13} /><span>{task.id}</span><ChevronRight size={13} /><strong>{selected?.id}</strong></div><div className="task-trace-grid"><div className="task-trace-events">{events.map((event) => <button className={event.id === selected?.id ? 'selected' : ''} key={event.id} onClick={() => setSelectedId(event.id)}><span className={`timeline-status ${event.tone}`}>{event.sequence}</span><span><small>{event.category} · {event.timestamp.slice(11, 19)}</small><strong>{event.actor}</strong><span>{event.result}</span></span><ChevronRight size={14} /></button>)}</div>{selected ? <AuditEventInspector event={selected} compact /> : null}</div></div>;
}

function AtomicEventLedger(): React.JSX.Element {
  const [query, setQuery] = useState('');
  const [category, setCategory] = useState<'all' | AuditEventCategory>('all');
  const [limit, setLimit] = useState(80);
  const filtered = enterpriseAuditEvents.filter((event) => (category === 'all' || event.category === category) && `${event.id} ${event.traceId} ${event.actor} ${event.workspace} ${event.action} ${event.policyRule} ${event.apiEndpoint}`.toLowerCase().includes(query.toLowerCase()));
  const [selectedId, setSelectedId] = useState(enterpriseAuditEvents[0].id);
  const selected = filtered.find((event) => event.id === selectedId) ?? filtered[0] ?? enterpriseAuditEvents[0];
  useEffect(() => setLimit(80), [query, category]);
  return <section className="atomic-ledger"><PanelHeader icon={<Database />} title="Atomic audit log" subtitle="Search every recorded intent, authorization, context release, provider call, policy decision, human review, and evidence seal" /><div className="atomic-ledger-toolbar"><label className="local-search"><Search size={16} /><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Search event ID, trace, actor, policy, or API" /></label><label className="select-control"><Filter size={16} /><select value={category} onChange={(event) => setCategory(event.target.value as 'all' | AuditEventCategory)}><option value="all">All event categories</option>{(['intent', 'authorization', 'context', 'provider-call', 'policy', 'human-review', 'evidence'] as AuditEventCategory[]).map((item) => <option key={item} value={item}>{item}</option>)}</select></label><span>{filtered.length.toLocaleString()} events</span></div><div className="atomic-ledger-grid"><div className="atomic-event-list"><div className="atomic-event-head"><span>Time / event</span><span>Actor</span><span>Action</span><span>Decision</span></div>{filtered.slice(0, limit).map((event) => <button className={event.id === selected.id ? 'selected' : ''} key={event.id} onClick={() => setSelectedId(event.id)}><span><code>{event.timestamp.slice(11, 23)}</code><small>{event.id}</small></span><span><strong>{event.actor}</strong><small>{event.actorType} · {event.workspace}</small></span><span><strong>{event.category}</strong><small>{event.action}</small></span><span><RiskChip risk={event.tone} label={event.decision} /></span></button>)}{limit < filtered.length ? <button className="atomic-load-more" onClick={() => setLimit((current) => current + 80)}>Load 80 more events</button> : null}</div><AuditEventInspector event={selected} /></div></section>;
}

function AuditEventInspector({ event, compact = false }: { event: AtomicAuditEvent; compact?: boolean }): React.JSX.Element {
  const decisionLabel = event.tone === 'healthy' ? event.decision : `${event.decision} · ${event.tone} risk`;
  return <aside className={`audit-event-inspector ${compact ? 'compact' : ''}`}><header><span className={`event-category-icon ${event.tone}`}><Activity size={17} /></span><div><span className="eyebrow">Atomic event · sequence {event.sequence}</span><h3>{event.category}</h3></div><RiskChip risk={event.tone} label={decisionLabel} /></header><div className="audit-event-outcome"><span>Action</span><strong>{event.action}</strong><span>Result</span><b>{event.result}</b></div><dl><div><dt>Event ID</dt><dd><code>{event.id}</code></dd></div><div><dt>Timestamp</dt><dd>{event.timestamp}</dd></div><div><dt>Actor</dt><dd>{event.actor} · {event.actorType}</dd></div><div><dt>Device/runtime</dt><dd>{event.device}</dd></div><div><dt>Parent trace</dt><dd><code>{event.traceId}</code></dd></div><div><dt>Task / evidence</dt><dd>{event.taskId} · {event.evidenceId}</dd></div><div><dt>Source</dt><dd>{event.source}</dd></div><div><dt>Destination</dt><dd>{event.destination}</dd></div><div><dt>Policy rule</dt><dd><code>{event.policyRule}</code></dd></div><div><dt>API</dt><dd>{event.apiEndpoint}</dd></div><div><dt>Latency</dt><dd>{event.latencyMs} ms</dd></div><div><dt>Released fields</dt><dd>{event.releasedFields}</dd></div><div><dt>Withheld fields</dt><dd>{event.withheldFields}</dd></div><div><dt>Input digest</dt><dd><code>{event.inputDigest}</code></dd></div><div><dt>Output digest</dt><dd><code>{event.outputDigest}</code></dd></div></dl><details className="raw-event-payload"><summary>Raw event payload</summary><pre>{JSON.stringify(event, null, 2)}</pre></details><button className="secondary-button full-button" onClick={() => downloadJson(`${event.id}.json`, event)}><Download size={16} />Export event</button></aside>;
}

function downloadJson(filename: string, value: unknown): void {
  const url = URL.createObjectURL(new Blob([JSON.stringify(value, null, 2)], { type: 'application/json' }));
  const anchor = document.createElement('a');
  anchor.href = url;
  anchor.download = filename;
  anchor.click();
  window.setTimeout(() => URL.revokeObjectURL(url), 0);
}

function EstateMesh({ nodes = estateNodes, edges = estateEdges, rootId = 'hq', selectedId, onSelect, onEnterWorkspace, compact = false, filter = 'all', query = '' }: { nodes?: EstateNode[]; edges?: EstateEdge[]; rootId?: string; selectedId: string; onSelect: (id: string) => void; onEnterWorkspace?: (id: string) => void; compact?: boolean; filter?: string; query?: string }): React.JSX.Element {
  const nodeMap = useMemo(() => new Map(nodes.map((node) => [node.id, node])), [nodes]);
  const related = new Set([selectedId]);
  edges.forEach((edge) => { if (edge.from === selectedId) related.add(edge.to); if (edge.to === selectedId) related.add(edge.from); });
  const visibleIds = new Set(nodes.map((node) => node.id));

  function visible(node: EstateNode): boolean {
    if (node.id === rootId) return true;
    if (filter === 'people') return node.type === 'human';
    if (filter === 'agents') return node.type === 'managed-agent' || node.type === 'third-party';
    if (filter === 'third-party') return node.type === 'third-party';
    return true;
  }

  function selectNode(node: EstateNode): void {
    onSelect(node.id);
    if (node.type === 'workspace' && node.id !== rootId && onEnterWorkspace) onEnterWorkspace(node.id);
  }

  const searchTerm = query.trim().toLowerCase();
  const matchesQuery = (node: EstateNode): boolean => !searchTerm || node.id === rootId || `${node.label} ${node.owner ?? ''} ${node.scope}`.toLowerCase().includes(searchTerm);
  return <div className={`estate-mesh ${compact ? 'compact' : ''} ${nodes.length > 40 ? 'dense' : ''}`}><svg viewBox="0 0 1000 560" preserveAspectRatio="none" aria-hidden="true">{edges.filter((edge) => visibleIds.has(edge.from) && visibleIds.has(edge.to)).map((edge) => { const from = nodeMap.get(edge.from)!; const to = nodeMap.get(edge.to)!; const filtered = !visible(from) || !visible(to) || !matchesQuery(from) || !matchesQuery(to); return <g key={`${edge.from}-${edge.to}-${edge.type}`} className={`mesh-edge ${edge.type} ${filtered || (selectedId !== rootId && !related.has(edge.from) && !related.has(edge.to)) ? 'dimmed' : ''}`}><line x1={from.x * 10} y1={from.y * 5.6} x2={to.x * 10} y2={to.y * 5.6} />{!compact && nodes.length <= 40 && edge.label ? <text x={(from.x + to.x) * 5} y={(from.y + to.y) * 2.8 - 7}>{edge.label}</text> : null}</g>; })}</svg>{nodes.map((node) => <button key={node.id} style={{ '--mesh-x': `${node.x}%`, '--mesh-y': `${node.y}%` } as React.CSSProperties} className={`mesh-node ${node.type} ${node.risk} ${node.id === rootId ? 'root' : ''} ${selectedId === node.id ? 'selected' : ''} ${!visible(node) || !matchesQuery(node) || (selectedId !== rootId && !related.has(node.id)) ? 'dimmed' : ''}`} onClick={() => selectNode(node)} aria-label={`${node.label}: ${node.subtitle}`} title={`${node.label}: ${node.activity}`}><span><NodeIcon node={node} /></span><strong>{node.label}</strong>{!compact ? <small>{node.subtitle}</small> : null}</button>)}</div>;
}

function NodeIcon({ node }: { node: EstateNode }): React.JSX.Element { if (node.type === 'organization' || node.type === 'workspace') return <Building2 />; if (node.type === 'human') return <UserRound />; if (node.type === 'data') return <Database />; return <Bot />; }
function nodeTypeLabel(type: EstateNode['type']): string { return ({ organization: 'Enterprise headquarters', workspace: 'Workspace', human: 'Employee identity', 'managed-agent': 'Managed agent', 'third-party': 'Third-party tool', data: 'Data object' })[type]; }
function CisoHeader({ eyebrow, title, subtitle, actions }: { eyebrow: string; title: string; subtitle: string; actions?: React.ReactNode }): React.JSX.Element { return <header className="ciso-header"><div><span className="eyebrow">{eyebrow}</span><h1>{title}</h1><p>{subtitle}</p></div>{actions ? <div className="page-actions">{actions}</div> : null}</header>; }
function PanelHeader({ icon, title, subtitle, action }: { icon: React.ReactNode; title: string; subtitle: string; action?: React.ReactNode }): React.JSX.Element { return <header className="ciso-panel-header"><span>{icon}</span><div><h2>{title}</h2><p>{subtitle}</p></div>{action}</header>; }
function Kpi({ value, label, detail, trend, tone, icon }: { value: string; label: string; detail: string; trend: string; tone: string; icon: React.ReactNode }): React.JSX.Element { return <article className={`estate-kpi ${tone}`}><span className="kpi-icon">{icon}</span><div><strong>{value}</strong><span>{label}</span><small>{detail}</small></div><b>{trend}</b></article>; }
function Outcome({ value, label, tone }: { value: string; label: string; tone: string }): React.JSX.Element { return <div className={`outcome ${tone}`}><strong>{value}</strong><span>{label}</span></div>; }
function MiniBars({ values, tone }: { values: number[]; tone: string }): React.JSX.Element { const max = Math.max(...values); return <div className={`mini-bars ${tone}`} aria-label={`Trend: ${values.join(', ')}`}>{values.map((value, index) => <span key={index} style={{ height: `${value / max * 100}%` }} />)}</div>; }
function RiskChip({ risk, label }: { risk: string; label?: string }): React.JSX.Element { return <span className={`risk-chip ${risk}`}><i />{label ?? risk}</span>; }
function InlineStat({ label, value, danger, warning }: { label: string; value: string | number; danger?: boolean; warning?: boolean }): React.JSX.Element { return <div className={danger ? 'danger' : warning ? 'warning' : ''}><strong>{value}</strong><span>{label}</span></div>; }
function TeamBar({ name, active, total }: { name: string; active: number; total: number }): React.JSX.Element { const percent = Math.round(active / total * 100); return <div className="team-bar"><span><strong>{name}</strong><small>{active} of {total} active</small></span><div><i style={{ width: `${percent}%` }} /></div><b>{percent}%</b></div>; }
function Signal({ tone, title, detail, action, onClick }: { tone: string; title: string; detail: string; action: string; onClick: () => void }): React.JSX.Element { return <button onClick={onClick}><span className={`signal-dot ${tone}`} /><span><strong>{title}</strong><small>{detail}</small></span><b>{action}</b><ChevronRight /></button>; }
function ActionList({ actions, selectedId, onOpen }: { actions: EstateAction[]; selectedId?: string; onOpen: (id: string) => void }): React.JSX.Element { return <div className="estate-action-list">{actions.map((action) => <button className={selectedId === action.id ? 'selected' : ''} key={action.id} onClick={() => onOpen(action.id)}><span className={`risk-symbol ${action.risk}`}><ShieldAlert /></span><span><strong>{action.title}</strong><small>{action.category} · {action.detected}</small></span><RiskChip risk={action.risk} /><ChevronRight /></button>)}</div>; }
function MeshLegend({ workspaceView }: { workspaceView: boolean }): React.JSX.Element {
  return <div className="mesh-legend">{workspaceView ? <><span><i className="human" />Person</span><span><i className="managed" />Company / employee agent</span><span><i className="third" />Third-party agent</span><span><em className="membership" />Membership</span><span><em className="active" />Active work</span><span><em className="review" />Needs review</span></> : <><span><i className="headquarters" />Headquarters</span><span><i className="human" />Workspace creator</span><span><i className="workspace" />Workspace</span><span><em className="membership" />Creator</span><span><em className="admin" />Additional admin</span><span><em className="cross" />Workspace communication</span></>}</div>;
}

function AgentDrawer({ agent, onClose, onContain }: { agent: InventoryAgent; onClose: () => void; onContain: () => void }): React.JSX.Element {
  return <div className="estate-drawer-layer" onMouseDown={(event) => { if (event.target === event.currentTarget) onClose(); }}><aside className="estate-drawer" role="dialog" aria-modal="true" aria-label={agent.name}><header><div><span className="eyebrow">Agent and tool record</span><h2>{agent.name}</h2></div><button className="icon-button" onClick={onClose} aria-label="Close"><X /></button></header><div className="estate-drawer-body"><div className="agent-record-hero"><span className={`entity-symbol ${agent.kind === 'Shadow AI' ? 'third-party critical' : agent.kind === 'Approved third-party' ? 'third-party' : 'managed-agent'}`}><Bot /></span><div><strong>{agent.kind}</strong><span>{agent.provider}</span></div><RiskChip risk={agent.risk} /></div><dl className="inspection-facts"><div><dt>Accountable owner</dt><dd>{agent.owner}</dd></div><div><dt>30-day calls</dt><dd>{agent.calls.toLocaleString()}</dd></div><div><dt>Unique users</dt><dd>{agent.users}</dd></div><div><dt>Data observed</dt><dd>{agent.data}</dd></div><div><dt>Monthly spend</dt><dd>{agent.spend}</dd></div><div><dt>Last used</dt><dd>{agent.lastUsed}</dd></div><div><dt>Runtime state</dt><dd>{agent.state}</dd></div></dl><section className="call-reason"><Zap /><div><strong>Why this agent is called</strong><p>{agent.id === 'windsurf' ? 'Selected locally by employees for code generation. No approved H2A selection policy or accountable owner was found.' : 'Selected by an approved workspace plan based on capability, ownership, and minimum required context.'}</p></div></section><section className="context-decision"><div><Check /><span><strong>Observed or released</strong><small>{agent.data}</small></span></div><div><LockKeyhole /><span><strong>Protected</strong><small>Credentials, unrelated workspaces, personal notes</small></span></div></section></div><footer>{agent.state !== 'quarantined' ? <button className="danger-button" onClick={onContain}>Quarantine connection</button> : <span className="resolved-state"><Check /><strong>Quarantined</strong></span>}<button className="secondary-button" onClick={onClose}>Close</button></footer></aside></div>;
}

function CheckCircle(): React.JSX.Element { return <CheckCircle2Icon />; }
function CheckCircle2Icon(): React.JSX.Element { return <span className="resolved-icon"><Check /></span>; }
